        double vik_xy = 0;
        double vik_xz = 0;
        double vik_yx = 0;
        double vik_yy = 0;
        double vik_yz = 0;
        double vik_zx = 0;
        double vik_zy = 0;
        double vik_zz = 0;
        double vjk_xx = 0;
        double vjk_xy = 0;
        double vjk_xz = 0;
        double vjk_yx = 0;
