        double vjl_xy = 0;
        double vjl_xz = 0;
        double vjl_yx = 0;
        double vjl_yy = 0;
        double vjl_yz = 0;
        double vjl_zx = 0;
        double vjl_zy = 0;
        double vjl_zz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        if (jk.n_dm == 1) {
            for (int n = gout_id; n < 162; n+=16) {
                int i = n % 6;
                int j = n / 6 % 3;
                int k = n / 18 % 3;
                int l = n / 54;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm[_jk] * dm[_il] + dm[_jl] * dm[_ik]);
                }
                if (do_j) {
                    dd += jk.j_factor * dm[_ji] * dm[_lk];
                }
                dd_cache[n*16] = fac_sym * dd;
            }
        } else {
            double *dmb = dm + nao * nao;
            for (int n = gout_id; n < 162; n+=16) {
                int i = n % 6;
                int j = n / 6 % 3;
                int k = n / 18 % 3;
                int l = n / 54;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += dm [_jk] * dm [_il] + dm [_jl] * dm [_ik];
                    dd += dmb[_jk] * dmb[_il] + dmb[_jl] * dmb[_ik];
                    dd *= jk.k_factor;
                }
                if (do_j) {
                    dd += jk.j_factor * (dm[_ji] + dmb[_ji]) * (dm[_lk] + dmb[_lk]);
                }
                dd_cache[n*16] = fac_sym * dd;
            }
        }
        if (gout_id == 0) {
            dd_cache[2592] = 0;
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
