                        _gx[400] = s2;
                        s0 = _gx[32];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[16];
                        _gx[160] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[144];
                        _gx[288] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 2 * b00 * _gx[272];
