                    vjj_zz += (aj2 * (aj2 * (vgx[(h & 1 ? 1792 : 2192)] - zjzi * vgx[(h & 1 ? 1776 : 2176)]) - 1.0 * vgx[(h & 1 ? 1728 : 2128)])) * S;
                    vij_zz += (aj2 * (ai2 * vgx[(h & 1 ? 1792 : 2192)] - (h & 1 ? 0.0 : 1.0) * vgx[(h & 1 ? 1728 : 2160)])) * S;
                    vkk_zz += (ak2 * (ak2 * (vgx[(h & 1 ? 2112 : 2512)] + zlzk * vgx[(h & 1 ? 1824 : 2224)]) - (h & 1 ? 1.0 : 3.0) * vgx[(h & 1 ? 1728 : 2128)])) * S;
                    vll_zz += (al2 * (al2 * (vgx[(h & 1 ? 2112 : 2512)] - zlzk * vgx[(h & 1 ? 2016 : 2416)]) - (h & 1 ? 1.0 : 3.0) * vgx[(h & 1 ? 1728 : 2128)])) * S;
                    vkl_zz += (al2 * (ak2 * vgx[(h & 1 ? 2112 : 2512)] - (h & 1 ? 0.0 : 1.0) * vgx[(h & 1 ? 1728 : 2320)]) - (h & 1 ? 0.0 : 1.0) * (ak2 * vgx[(h & 1 ? 1728 : 1936)] - (h & 1 ? 0.0 : 1.0) * vgx[(h & 1 ? 1728 : 1744)])) * S;
                    vij_zx += Ai * T1;
                    vij_xz += Aj * T0;
                    vjj_xz += Aj * T1;
                    vii_xz += Ai * T0;
                    vkl_zx += Ak * T3;
                    vkl_xz += Al * T2;
                    vll_xz += Al * T3;
                    vkk_xz += Ak * T2;
